function pad(d,t,f,a,dur){ [1,1.004].forEach(k=>osc(d,t,"triangle",f*k,a,dur*.35,dur*.65)); osc(d,t,"sine",f/2,a*.8,dur*.3,dur*.7) }
function vib(d,t,f,a,att,dec,rate,depth){ const o=ctx.createOscillator(), g=ctx.createGain(), l=ctx.createOscillator(), lg=ctx.createGain();
  o.frequency.setValueAtTime(f,t); l.frequency.value=rate; lg.gain.value=f*depth; l.connect(lg); lg.connect(o.frequency);
  env(g,t,a,att,dec); o.connect(g); g.connect(d); o.start(t); l.start(t); o.stop(t+att+dec+.05); l.stop(t+att+dec+.05) }
function bell(d,t,f,a,dur=2.2){ [[1,1],[2,.5],[2.42,.35],[3,.25],[4.1,.15],[5.4,.08]].forEach(([k,m])=>osc(d,t,"sine",f*k,a*m,.002,dur*(1.2-k*.15))) }
