function chime(d,t,f,a,dur=1.4){ osc(d,t,"sine",f,a,.004,dur); osc(d,t,"sine",f*2.005,a*.25,.004,dur*.6); osc(d,t,"triangle",f*3.01,a*.06,.004,dur*.3) }
