function timp(d,t,f,a){ osc(d,t,"sine",f*1.5,a,.003,1.3,f); osc(d,t,"sine",f*2.4,a*.25,.003,.35,f*1.6); env(noise(d,t,.12,[{type:"lowpass",f:900}]),t,a*.4,.002,.1) }
