function swell(d,t,a,dur){ const g=noise(d,t,dur,[{type:"highpass",f:3500}]); g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(a,t+dur); g.gain.setValueAtTime(.0001,t+dur+.01) }
