    chord:(d,t,ns,a,dur,z,dr)=>{ ns.forEach((n,i)=>harp(d,t+i*.045,NOTE(n-12),a*.75,dur*1.2)); mbox(d,t+ns.length*.045,NOTE(ns.at(-1)),a*.7,dur); if(z>=3||dr>=2) strings(d,t,NOTE(ns[0]-12),.025+.008*dr,dur*1.4) },
    bass:(d,t,f,dur)=>harp(d,t,f,.3,dur*1.2),
