    legend:(d,t,ns,dur)=>{ for(let i=0;i<16;i++) harp(d,t-.5+i*.03,NOTE(ns[0]-12+[0,2,4,7,9][i%5]+12*Math.floor(i/5)),.12,1.2); ns.forEach((n,i)=>chime(d,t+.05+i*.05,NOTE(n),.06,2)) },
